contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dummy) public {
        require(dummy < 1000000 ether);
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(c.depositsCount() == beforeCount && address(c).balance <= beforeBal);
    }
    receive() external payable {}
}

